-- Backend-only schema; no Supabase browser/Data API role is authorized.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='erp_backend') THEN CREATE ROLE erp_backend NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF; END $$;
REVOKE ALL ON SCHEMA :SCHEMA: FROM PUBLIC;
GRANT USAGE ON SCHEMA :SCHEMA: TO erp_backend;
REVOKE ALL ON ALL TABLES IN SCHEMA :SCHEMA: FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA :SCHEMA: FROM PUBLIC;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA :SCHEMA: FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA :SCHEMA: REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA :SCHEMA: REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
