GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA :SCHEMA: TO erp_backend; GRANT EXECUTE ON FUNCTION instr(text,text) TO erp_backend;
DO $$ DECLARE r text; BEGIN FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON SCHEMA :SCHEMA: FROM %I',r); EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA :SCHEMA: FROM %I',r); EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA :SCHEMA: FROM %I',r); END IF; END LOOP; END $$;
